style.css:
@-moz-document domain("coupang.com") {
/* =========================
   기본 배경
========================= */
html, body {
    background-color: #0f0f0f !important;
    color: #ffffff !important;
}

/* =========================
   글씨 전체 강제 밝게 (강화)
========================= */
body, p, a, span, div, li, h1, h2, h3, h4, h5, h6, strong, em, b {
    color: #ffffff !important;
}

/* 쿠팡이 따로 지정하는 텍스트 클래스 대응 */
[class*="name"],
[class*="title"],
[class*="price"],
[class*="desc"],
[class*="product"] {
    color: #ffffff !important;
}

/* =========================
   흰 배경 제거 (유지)
========================= */
div, section, article, aside, header, nav, ul, li, main {
    background-color: transparent !important;
}

/* 밝은 UI 박스 제거 */
[class*="white"],
[class*="White"],
[class*="bg-white"],
[class*="BgWhite"],
[class*="light"],
[class*="Light"] {
    background-color: transparent !important;
}

/* =========================
   검색창 유지
========================= */
input, textarea, select {
    background-color: #1c1c1c !important;
    color: #ffffff !important;
    border: 1px solid #333 !important;
}

input::placeholder {
    color: #aaaaaa !important;
}

/* =========================
   헤더 유지
========================= */
header, #header, .header-wrap, nav {
    background-color: #151515 !important;
}

/* 헤더 내부 글씨 유지 */
header *, #header *, .header-wrap * {
    color: #ffffff !important;
}

/* =========================
   상품 카드
========================= */
li, article, [class*="product"], [class*="item"] {
    background-color: transparent !important;
    border: 1px solid #2a2a2a !important;
}

/* =========================
   링크
========================= */
a {
    color: #4da3ff !important;
}

/* =========================
   이미지 유지
========================= */
img {
    filter: none !important;
    opacity: 1 !important;
}
}
